local config = {
  ui_story_5048_50480101_1_dialog_content = "<color=#e8d9bb>Piu, piu, grito...</color>",
  ui_story_5048_50480101_2_dialog_content = "<color=#e8d9bb>Twin Pavilions Bay - Distrito Oeste</color>",
  ui_story_5048_50480101_3_dialog_content = "Sua Alteza?",
  ui_story_5048_50480101_4_dialog_content = "<size=50>Princesa Dantang!</size>",
  ui_story_5048_50480101_5_dialog_content = "Hum?",
  ui_story_5048_50480101_6_dialog_content = "Seus olhos estavam fechados tão apertados, Sua Alteza, e você estava tão silencioso... Por favor, diga, está sentindo algum desconforto?",
  ui_story_5048_50480101_7_dialog_content = "Desculpe por preocupar você, Jiu, eu estava apenas concentrado nesta maravilhosa e doce peça de piano.",
  ui_story_5048_50480101_8_dialog_content = "Ouça - é tão suave quanto a água, mas também possui uma elegância grandiosa. É completamente diferente dos instrumentos de Longzhou. Que deleite para os ouvidos.",
  ui_story_5048_50480101_9_dialog_content = "Se eu tiver a chance no futuro, adoraria tocar ao lado de um pianista e, quem sabe, você possa realizar uma dança com espadas ao meu lado...",
  ui_story_5048_50480101_10_dialog_content = "Você é um verdadeiro visionário, Sua Alteza.",
  ui_story_5048_50480101_11_dialog_content = "Não acha estranho? Dizem que a <color=#FFB400>Twin Pavilions Bay</color> tem muita chuva e um clima agradável nesta época do ano... No entanto, tem estado tão quente e seco recentemente.",
  ui_story_5048_50480101_12_dialog_content = "Esta é sua primeira vez em Twin Pavilions Bay?",
  ui_story_5048_50480101_13_dialog_content = "O clima tem estado meio incomum em Twin Pavilions Bay este ano. Estamos todos ansiosos por uma brisa marinha fresca e uma boa chuva.",
  ui_story_5048_50480101_14_dialog_content = "Ops, desculpe, me desviei um pouco do assunto. Aqui está o seu pedido, todos os pratos que você pediu.",
  ui_story_5048_50480101_15_dialog_content = "Esperamos que a bela paisagem possa dissipar qualquer desconforto causado pelo clima quente. Aproveite sua refeição.",
  ui_story_5048_50480101_16_dialog_content = "Como esperado do restaurante mais famoso de Twin Pavilions Bay - o serviço aqui é realmente excepcional.",
  ui_story_5048_50480101_17_dialog_content = "Sua Alteza, há uma coisa que ainda não entendo bem.",
  ui_story_5048_50480101_18_dialog_content = "A Pequena Longzhou, no leste da cidade, abriga muitos restaurantes que servem os pratos no estilo Longzhou aos quais você está tão acostumado.",
  ui_story_5048_50480101_19_dialog_content = "Então, por que você insiste em frequentar este restaurante Astra no oeste da cidade quando a fome bate?",
  ui_story_5048_50480101_20_dialog_content = "O primeiro passo da diplomacia é entender os costumes e tradições locais, e o primeiro passo para adquirir tal entendimento é...",
  ui_story_5048_50480101_21_dialog_content = "Bem, naturalmente, começar com a comida local é o jeito mais rápido.",
  ui_story_5048_50480101_22_dialog_content = "Você está absolutamente certo, Sua Alteza.",
  ui_story_5048_50480101_23_dialog_content = "Hmm? Perdoe minha negligência, eu deveria ter pedido para prepararem os pauzinhos para nossa mesa. Vou chamar o garçom.",
  ui_story_5048_50480101_24_dialog_content = "Olha, Jiu, essas facas e garfos são os talheres daqui.",
  ui_story_5048_50480101_25_dialog_content = "Facas e garfos... como talheres? Por que eles parecem mais como armas pessoais para mim?",
  ui_story_5048_50480101_26_dialog_content = "Haha. Eu sei que você precisa praticar suas artes marciais o dia todo, mas você realmente precisa ler alguns dos livros que te dei quando tiver tempo. Aprenda algo sobre a cultura daqui.",
  ui_story_5048_50480101_27_dialog_content = "Sim...",
  ui_story_5048_50480101_28_dialog_content = "Bem, se os talheres estão prontos, por que não está comendo, Alteza?",
  ui_story_5048_50480101_29_dialog_content = "Eu estava apenas me perguntando como você vai comer com essa máscara?",
  ui_story_5048_50480101_30_dialog_content = "Sua Alteza, vou servi-lo enquanto você janta, é claro.",
  ui_story_5048_50480101_31_dialog_content = "Ainda não se acostumou a mostrar seu rosto em público?",
  ui_story_5048_50480101_32_dialog_content = "Receio que minha aparência possa ofender os olhos de Vossa Alteza, tornando Vossa Alteza incapaz de comer...",
  ui_story_5048_50480101_33_dialog_content = "Tudo bem, mas eu não te disse que nem a palavra \"linda\" faz jus à sua aparência? Por que você ainda não acredita em mim?",
  ui_story_5048_50480101_34_dialog_content = "Oh, devo comer toda essa comida deliciosa sozinho? Você está tão ansioso para me ver sofrendo de indigestão?",
  ui_story_5048_50480101_35_dialog_content = "Eu jamais sonharia com algo assim!",
  ui_story_5048_50480101_36_dialog_content = "Ahem... Vamos lá, tente.",
  ui_story_5048_50480101_37_dialog_content = "... Sim, Sua Alteza!",
  ui_story_5048_50480101_38_dialog_content = "<color=#e8d9bb>Jiu experimentou cuidadosamente todos os pratos.</color>",
  ui_story_5048_50480101_39_dialog_content = "O que você achou?",
  ui_story_5048_50480101_40_dialog_content = "Vossa Alteza, eu provei tudo e pode ficar tranquilo que a comida não está envenenada.",
  ui_story_5048_50480101_41_dialog_content = "Quero saber o que você acha do sabor. Está do seu agrado?",
  ui_story_5048_50480101_42_dialog_content = "Isso... Eu não estava prestando atenção.",
  ui_story_5048_50480101_43_dialog_content = "Na próxima vez, saboreie cada mordida cuidadosamente comigo. Tenha certeza de não desperdiçar essas iguarias raras novamente.",
  ui_story_5048_50480101_44_dialog_content = "Entendi. Vossa Alteza não pretendia que eu provasse a comida para verificar se havia veneno...",
  ui_story_5048_50480101_45_dialog_content = "Claro. Como mais você poderá aproveitar essa comida deliciosa comigo?",
  ui_story_5048_50480101_46_dialog_content = "Sua Alteza, peço que aguarde um momento!",
  ui_story_5048_50480101_47_dialog_content = "Ao olhar mais de perto agora, percebi algo...",
  ui_story_5048_50480101_48_dialog_content = "O recheio desta Pizza de Forno de Pedra na verdade não foi assado na massa...",
  ui_story_5048_50480101_49_dialog_content = "Este Beef Roayl não foi cozido corretamente! Olhe só todas as marcas de sangue passando por ele!",
  ui_story_5048_50480101_50_dialog_content = "E esta Salada Sazonal com Mel claramente contém vegetais crus! Eles não foram cozidos de forma alguma!",
  ui_story_5048_50480101_51_dialog_content = "Pratos feitos de forma tão descuidada podem realmente ser chamados de iguarias de Twin Pavilions Bay?",
  ui_story_5048_50480101_52_dialog_content = "Acalme-se, Jiu—não seja impaciente. Como diz o ditado, o ambiente desempenha um papel significativo no desenvolvimento de alguém.",
  ui_story_5048_50480101_53_dialog_content = "Lembre-se, diferenças regionais na dieta existem entre os vários reinos vassalos de Longzhou, e essas diferenças são ainda mais distintas em Astra, já que é separado de nós por um vasto oceano.",
  ui_story_5048_50480101_54_dialog_content = "Aprender a apreciar as culinárias de diferentes regiões é outra das lições que devemos aprender em nossa jornada pelo mundo.",
  ui_story_5048_50480101_55_dialog_content = "Esta Pizza de Forno de Pedra não é uma das nossas tortas de Longzhou.",
  ui_story_5048_50480101_56_dialog_content = "Esta pizza foi especialmente assada em um forno de pedra de alta temperatura e, idealmente, deve ter uma crosta crocante, recheio completo e queijo fresco e perfumado.",
  ui_story_5048_50480101_57_dialog_content = "E esse Bife Real?",
  ui_story_5048_50480101_58_dialog_content = "Em Longzhou, costumamos refogar nossa carne até que fique macia e suave, e temperamos com diferentes condimentos.",
  ui_story_5048_50480101_59_dialog_content = "No entanto, este Beef Royal busca preservar o sabor original dos ingredientes o máximo possível. A carne é fresca, macia e suculenta, e derrete na boca...",
  ui_story_5048_50480101_60_dialog_content = "Se a qualidade da carne não fosse controlada rigorosamente desde a fase de criação, seria impossível produzir um sabor como esse.",
  ui_story_5048_50480101_61_dialog_content = "Dizem que, no passado, apenas o prestigioso Nobre Lumo tinha permissão para provar este prato.",
  ui_story_5048_50480101_62_dialog_content = "Entendi... E qual é a história por trás dessa Salada Sazonal com Mel?",
  ui_story_5048_50480101_63_dialog_content = "Esses vegetais são realmente muito frescos e estão presentes em grande variedade. Na verdade, muitos deles não são cultivados localmente.",
  ui_story_5048_50480101_64_dialog_content = "Um restaurante que pode fornecer vegetais frescos para os clientes de outros lugares em um calor tão abrasador...",
  ui_story_5048_50480101_65_dialog_content = "Seja mantendo a boa fé ou armazenando e preservando alimentos, tudo o que eles fazem é de primeira classe.",
  ui_story_5048_50480101_66_dialog_content = "O único problema é que este molho é um pouco doce demais para o meu gosto. Se ao menos os clientes pudessem escolher seus próprios molhos.",
  ui_story_5048_50480101_67_dialog_content = "Sua Alteza, embora tenha se familiarizado recentemente com as iguarias de Astra, já desenvolveu um entendimento tão profundo delas... Você é realmente a joia da coroa do Reino Ye!",
  ui_story_5048_50480101_68_dialog_content = "Jiu, por que você tem me lisonjeado tanto ultimamente?",
  ui_story_5048_50480101_69_dialog_content = "Será que você aprendeu alguns truques com algum <color=#FFB400>conversador habilidoso</color> a bordo do navio durante nossa viagem até aqui?",
  ui_story_5048_50480101_70_dialog_content = "Se Sua Alteza não gostar, falarei menos.",
  ui_story_5048_50480101_71_dialog_content = "Jiu, você realmente precisa aprender a reconhecer e reagir às provocações brincalhonas...",
  ui_story_5048_50480101_72_dialog_content = "Hum?",
  ui_story_5048_50480101_73_dialog_content = "O que pensa que está fazendo?!",
  ui_story_5048_50480101_74_dialog_content = "Ah...",
  ui_story_5048_50480101_75_dialog_content = "Você está assustando-os.",
  ui_story_5048_50480101_76_dialog_content = "Perdoe minha grosseria.",
  ui_story_5048_50480101_77_dialog_content = "Mas você interrompeu nós dois no meio da nossa refeição. Qual é o problema?",
  ui_story_5048_50480101_78_dialog_content = "Eh, é o seguinte.",
  ui_story_5048_50480101_79_dialog_content = "Nosso chefe, Sr. Ernest, acabou de ouvir seu feedback sobre nossos pratos e ficou agradavelmente surpreso.",
  ui_story_5048_50480101_80_dialog_content = "\"Ter percepções tão precisas sobre nossa culinária local na sua primeira tentativa é realmente notável.\"",
  ui_story_5048_50480101_81_dialog_content = "Nosso chefe gostaria de convidar vocês dois para a nossa cozinha e discutir a arte da culinária, se tiverem tempo para isso.",
  ui_story_5048_50480101_82_dialog_content = "Vocês dois considerariam nos agraciar com sua presença?",
  ui_story_5048_50480101_83_dialog_content = "Você é muito gentil, eu apenas dei algumas opiniões sinceras que podem não ser convencionais anteriormente.",
  ui_story_5048_50480101_84_dialog_content = "É muito generoso do proprietário nos convidar, e sua mente aberta é realmente admirável. Ficaremos mais do que felizes em aceitar seu convite.",
  ui_story_5048_50480101_85_dialog_content = "Sua Alteza! Somos novos aqui e ainda não estamos familiarizados com os costumes locais.",
  ui_story_5048_50480101_86_dialog_content = "Se aceitarmos imprudentemente um convite de um estranho e desaparecermos da vista do público, pode ser que...",
  ui_story_5048_50480101_87_dialog_content = "Se você me conhece, deve saber que eu não sou exatamente uma pessoa fraca, sem forças para me defender.",
  ui_story_5048_50480101_88_dialog_content = "Além disso, não estou acompanhado por um guarda-costas com habilidades incomparáveis em artes marciais?",
  ui_story_5048_50480101_89_dialog_content = "Claro, estarei aqui naturalmente para te proteger.",
  ui_story_5048_50480101_90_dialog_content = "Embora ainda não tenhamos tido a chance de discutir a arte do piano com o pianista... discutir iguarias com um gourmet primeiro também é uma ótima oportunidade.",
  ui_story_5048_50480101_91_dialog_content = "E assim, peço que você mostre o caminho, se isso lhe agradar.",
  ui_story_5048_50480101_92_dialog_content = "Estimados convidados, por favor, sigam por aqui.",
  ui_story_5048_50480101_93_dialog_content = "<color=#e8d9bb>Uma série de cliques e barulhos!</color>",
  ui_story_5048_50480101_94_dialog_content = "Oh não, será que alguém derrubou os pratos enquanto servia? O chefe vai ficar bravo de novo...",
  ui_story_5048_50480101_95_dialog_content = "E-Eu preciso de ajuda aqui!",
  ui_story_5048_50480101_96_dialog_content = "Socorro!",
  ui_story_5048_50480101_97_dialog_content = "Quê? Isso é...",
  ui_story_5048_50480101_98_dialog_content = "Li Tianxian?!",
  ui_story_5048_50480201_1_dialog_content = "<color=#e8d9bb>Há algum tempo</color>",
  ui_story_5048_50480201_2_dialog_content = "<color=#e8d9bb>Piu, piu, grito...</color>",
  ui_story_5048_50480201_3_dialog_content = "Melão dourado encolheu.",
  ui_story_5048_50480201_4_dialog_content = "Data de prata afundou.",
  ui_story_5048_50480201_5_dialog_content = "Barriga vazia ronca.",
  ui_story_5048_50480201_6_dialog_content = "Bolso do pobre faz clank!",
  ui_story_5048_50480201_7_dialog_content = "... Grasna, Jabber, vocês dois podem se acalmar por um momento?",
  ui_story_5048_50480201_8_dialog_content = "Férias! Férias!",
  ui_story_5048_50480201_9_dialog_content = "Vá para casa! Vá para casa!",
  ui_story_5048_50480201_10_dialog_content = "Se os negócios não melhorarem logo, de onde tiraremos o dinheiro para os melões dourados e as tâmaras prateadas?",
  ui_story_5048_50480201_11_dialog_content = "Mas não se preocupe. Eu perambulo pelo mundo, vagando por aqui e ali. Quando foi que eu já deixei vocês dois passarem fome?",
  ui_story_5048_50480201_12_dialog_content = "Espere só um pouquinho mais...",
  ui_story_5048_50480201_13_dialog_content = "Hum?",
  ui_story_5048_50480201_14_dialog_content = "Apenas olhe, nossa mudança de destino não está próxima?",
  ui_story_5048_50480201_15_dialog_content = "Bem-vindo! Senhor, você vai jantar sozinho?",
  ui_story_5048_50480201_16_dialog_content = "Estou à procura de alguém.",
  ui_story_5048_50480201_17_dialog_content = "Ele está lá dentro - posso encontrá-lo sozinho, não precisa se incomodar!",
  ui_story_5048_50480201_18_dialog_content = "Tudo bem, senhor.",
  ui_story_5048_50480201_19_dialog_content = "Incrível... É tão espaçoso e iluminado aqui, e muito mais fresco do que lá fora. Que pequena maravilha eu encontrei.",
  ui_story_5048_50480201_20_dialog_content = "Agora, é hora de começar a busca. Deixe-me ver...",
  ui_story_5048_50480201_21_dialog_content = "Bem, pedra nos corvos!",
  ui_story_5048_50480201_22_dialog_content = "É fácil ver que você é uma pessoa de grande riqueza e estatura, mas o que fez suas sobrancelhas se franzirem e seu rosto se encher de melancolia hoje?",
  ui_story_5048_50480201_23_dialog_content = "Algo está te incomodando.",
  ui_story_5048_50480201_24_dialog_content = "Seja o que for, acho que não tem nada a ver com você.",
  ui_story_5048_50480201_25_dialog_content = "Ah, sério? Mas como isso não pode ter nada a ver comigo?",
  ui_story_5048_50480201_26_dialog_content = "Permita-me me apresentar. Eu sou Li Tianxian, recém-chegado da balsa de Longzhou.",
  ui_story_5048_50480201_27_dialog_content = "Embora eu não possa falar sobre minhas próprias habilidades, alguns me consideram uma espécie de grande artesão.",
  ui_story_5048_50480201_28_dialog_content = "Um artesão, hein? Você não é um chef, por acaso?",
  ui_story_5048_50480201_29_dialog_content = "Não, não, não. Veja bem, vida e morte são ditadas pelo destino, riqueza e prestígio pelos céus. Eu sou um mestre do princípio do Yin e Yang e da teoria dos Cinco Elementos - com uma taxa mínima garantida de precisão de previsão de noventa por cento.",
  ui_story_5048_50480201_30_dialog_content = "Minha habilidade é conhecida como <color=#FFB400>adivinhação</color>.",
  ui_story_5048_50480201_31_dialog_content = "Posso traçar o curso do seu destino, guiá-lo com segurança pelos perigos do destino e, às vezes... até mesmo mudar o futuro, desafiando os próprios céus.",
  ui_story_5048_50480201_32_dialog_content = "Qualquer dificuldade que você esteja enfrentando, coloque-a em minhas mãos e eu lhe darei uma solução.",
  ui_story_5048_50480201_33_dialog_content = "Satisfação garantida!",
  ui_story_5048_50480201_34_dialog_content = "Precisão total, ou seu dinheiro de volta!",
  ui_story_5048_50480201_35_dialog_content = "Senhor, se você não está aqui para jantar, por favor, evite perturbar nossos estimados convidados e saia agora.",
  ui_story_5048_50480201_36_dialog_content = "Agora, agora, agora... Há um tempo e um lugar para tudo, e neste momento, ainda não terminei de falar com seu ilustre convidado.",
  ui_story_5048_50480201_37_dialog_content = "Você não vai pelo menos pensar sobre isso?",
  ui_story_5048_50480201_38_dialog_content = "Se você não estiver satisfeito, vou embora.",
  ui_story_5048_50480201_39_dialog_content = "Deixe-o sentar-se.",
  ui_story_5048_50480201_40_dialog_content = "Sr. Victor...?",
  ui_story_5048_50480201_41_dialog_content = "Não se preocupe com isso, vá em frente e volte aos seus deveres.",
  ui_story_5048_50480201_42_dialog_content = "Heheh, meu amigo, você deveria tentar ser mais respeitoso com seus clientes no futuro.",
  ui_story_5048_50480201_43_dialog_content = "...",
  ui_story_5048_50480201_44_dialog_content = "Sr. Victor, todos que trabalham aqui parecem conhecê-lo. Você deve ser um cliente assíduo.",
  ui_story_5048_50480201_45_dialog_content = "Sim, você pode dizer isso.",
  ui_story_5048_50480201_46_dialog_content = "Obrigado pela sua gentil ajuda agora há pouco!",
  ui_story_5048_50480201_47_dialog_content = "Encontrar uma alma tão gentil e justa como a sua é um acontecimento raro nos dias de hoje. Sendo assim, concederei a você uma adivinhação com preço promocional.",
  ui_story_5048_50480201_48_dialog_content = "Se seus poderes realmente forem tão impressionantes quanto você afirma, não vou tratá-lo injustamente.",
  ui_story_5048_50480201_49_dialog_content = "Agora, me mostre do que você é capaz.",
  ui_story_5048_50480201_50_dialog_content = "<color=#e8d9bb>Whooooosh!!</color>",
  ui_story_5048_50480201_51_dialog_content = "Rato Yin acima, Boi Yang abaixo.",
  ui_story_5048_50480201_52_dialog_content = "Bom senhor, a adivinhação mostra um rato cavalgando nas costas de um boi.",
  ui_story_5048_50480201_53_dialog_content = "A alternância de yin e yang, conflito universal - toda discórdia está interligada com causa e efeito.",
  ui_story_5048_50480201_54_dialog_content = "A imagem mostrada neste hexagrama revela sua futura estratégia para superar este conflito.",
  ui_story_5048_50480201_55_dialog_content = "Hum? Vamos ouvir então.",
  ui_story_5048_50480201_56_dialog_content = "Em primeiro lugar, se você não quer se tornar um degrau para o sucesso dos outros, deve tomar precauções extras contra aqueles que desejam prejudicá-lo.",
  ui_story_5048_50480201_57_dialog_content = "Como posso saber quem está tentando me prejudicar?",
  ui_story_5048_50480201_58_dialog_content = "Não se preocupe, senhor, pois esta adivinhação tem um segundo significado.",
  ui_story_5048_50480201_59_dialog_content = "Embora você possa encontrar pessoas de natureza desprezível, sempre receberá a ajuda dos virtuosos em momentos de perigo, encontrando um novo caminho a seguir e transformando infortúnios em bênçãos.",
  ui_story_5048_50480201_60_dialog_content = "Virtuoso, você diz?",
  ui_story_5048_50480201_61_dialog_content = "Isso quer dizer que, no último momento, alguém virá em seu socorro e todos os seus problemas serão resolvidos com facilidade.",
  ui_story_5048_50480201_62_dialog_content = "E você sempre será abençoado com boa sorte, ao longo de toda a sua vida.",
  ui_story_5048_50480201_63_dialog_content = "Hahaha! Excelente! Eu pagarei com prazer por essas palavras auspiciosas. Espero realmente ser abençoado com boa sorte, assim como você disse.",
  ui_story_5048_50480201_64_dialog_content = "Oh, você realmente é uma alma bondosa... Meu nobre benfeitor, por favor aceite minha mais profunda gratidão e uma reverência ainda mais profunda de seu humilde servo.",
  ui_story_5048_50480201_65_dialog_content = "Hmph! Você se considera um artesão, só porque sabe dizer às pessoas o que elas querem ouvir?",
  ui_story_5048_50480201_66_dialog_content = "E o fato de você estar fazendo tudo isso por um pouco de dinheiro torna você ainda mais desprezível.",
  ui_story_5048_50480201_67_dialog_content = "...",
  ui_story_5048_50480201_68_dialog_content = "Senhor, não tenho má vontade contra você. Por qual motivo você sente a necessidade de me repreender tão severamente?",
  ui_story_5048_50480201_69_dialog_content = "Tais palavras não me afetam pessoalmente, mas se elas abalarem seu próprio humor, certamente suas perdas superam seus ganhos.",
  ui_story_5048_50480201_70_dialog_content = "A comida de hoje está do seu agrado?",
  ui_story_5048_50480201_71_dialog_content = "(As palavras dele são duras, mas ele não parece ter algo contra mim...)",
  ui_story_5048_50480201_72_dialog_content = "Sim, é delicioso.",
  ui_story_5048_50480201_73_dialog_content = "Como você saberia o gosto se nem sequer deu uma mordida?",
  ui_story_5048_50480201_74_dialog_content = "É isso que você realmente quer da vida? Fingir que está tudo bem e buscar uma aparência superficial de paz?",
  ui_story_5048_50480201_75_dialog_content = "Você é um gourmet. Desconsiderar qualquer prato à sua frente como delicioso é o começo do fim para um homem de padrões!",
  ui_story_5048_50480201_76_dialog_content = "Existem mais de um conjunto de padrões neste mundo, e eu tenho minha própria maneira de ver as coisas.",
  ui_story_5048_50480201_77_dialog_content = "Apenas apontar as verdades desagradáveis do mundo não é suficiente para sobreviver nele. Se não conseguimos nem alcançar uma paz superficial, que esperança temos de alcançar a paz verdadeira?!",
  ui_story_5048_50480201_78_dialog_content = "(Tsc... Tenho medo de que outro mistério possa estar por trás do confronto entre esses dois.)",
  ui_story_5048_50480201_79_dialog_content = "Meu bom amigo, por favor, não se exalte assim. Lembra da adivinhação de agora há pouco?",
  ui_story_5048_50480201_80_dialog_content = "Esse tipo de angústia emocional certamente alimentará seu fogo interior, o que pode facilmente levar a uma rápida deterioração da sua saúde. Se o seu NEMESIS atacar enquanto você estiver nesse estado, seu salvador não estará por perto e a tragédia se seguirá.",
  ui_story_5048_50480201_81_dialog_content = "Isso realmente faz sentido, Mestre Li.",
  ui_story_5048_50480201_82_dialog_content = "Acho que você tem ouvido demais as bobagens desse charlatão!",
  ui_story_5048_50480201_83_dialog_content = "Ah, pelo amor de Deus, senhor. O infortúnio vem da boca. Tenha cuidado, para não ter que engolir essas palavras.",
  ui_story_5048_50480201_84_dialog_content = "Hmm? Senhor, a cor do espaço entre seus olhos está diferente. Isso pode ser um sinal preocupante...",
  ui_story_5048_50480201_85_dialog_content = "Que tal isso - vou te dar uma adivinhação grátis e vamos esquecer o que aconteceu aqui hoje. O que você acha?",
  ui_story_5048_50480201_86_dialog_content = "Não acredito em você por um segundo!",
  ui_story_5048_50480201_87_dialog_content = "<color=#e8d9bb>Uau!!!</color>",
  ui_story_5048_50480201_88_dialog_content = "Hmm? Parece que você acidentalmente pegou dois papéis para formar uma adivinhação. Isso é...",
  ui_story_5048_50480201_89_dialog_content = "Cavalo Yin e Boi Yin?!",
  ui_story_5048_50480201_90_dialog_content = "Um boi morto puxa um cavalo de madeira - nenhum deles consegue avançar. Senhor, você deve ter muito cuidado!",
  ui_story_5048_50480201_91_dialog_content = "O desastre pode acontecer a qualquer momento. Você deve eliminar todas as ameaças potenciais imediatamente e manter a calma!",
  ui_story_5048_50480201_92_dialog_content = "Emm...",
  ui_story_5048_50480201_93_dialog_content = "Ernesto?",
  ui_story_5048_50480201_94_dialog_content = "Ugh...",
  ui_story_5048_50480201_95_dialog_content = "Qual é o seu problema? Se tem algo pra dizer, é só falar...",
  ui_story_5048_50480201_96_dialog_content = "Tudo isso está se concretizando bem rápido...",
  ui_story_5048_50480201_97_dialog_content = "Urrgh...",
  ui_story_5048_50480201_98_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5048_50480201_99_dialog_content = "<color=#e8d9bb>Uma série de cliques e barulhos!</color>",
  ui_story_5048_50480201_100_dialog_content = "E-Eu preciso de ajuda aqui!",
  ui_story_5048_50480201_101_dialog_content = "Socorro!",
  ui_story_5048_50480201_102_dialog_content = "Desastre acontece! Salve a vida dele!",
  ui_story_5048_50480201_103_dialog_content = "Socorro! Alguém, ajude!",
  ui_story_5048_50480201_104_dialog_content = "Tianxian, o que você está fazendo aqui?",
  ui_story_5048_50480201_105_dialog_content = "Senhorita Jiu? Princesa Dantang? Realmente não há história sem coincidências, nem encontro sem predestinação...",
  ui_story_5048_50480201_106_dialog_content = "Chefe?!",
  ui_story_5048_50480201_107_dialog_content = "Chefe, o que aconteceu com você? Vamos lá, acorde...",
  ui_story_5048_50480201_108_dialog_content = "Pele pálida, espumando pela boca... Testa vermelha em chamas?",
  ui_story_5048_50480201_109_dialog_content = "Esses sintomas... Isso não é envenenamento por <color=#FFB400>chama de corvo</color>?",
  ui_story_5048_50480201_110_dialog_content = "Ravenflame é um analgésico com propriedades aquecedoras, mas só pode ser aplicado topicamente, não pode ser ingerido!",
  ui_story_5048_50480201_111_dialog_content = "Caso contrário... Bem, casos leves de envenenamento por ravenflame envolvem vômitos, diarreia e dormência em todo o corpo, enquanto casos graves são marcados por dificuldade para respirar, convulsões, delírio e parada cardíaca.",
  ui_story_5048_50480201_112_dialog_content = "Tamanha traição impiedosa...",
  ui_story_5048_50480201_113_dialog_content = "Jiu, pressione o ponto de acupuntura fuquan dele e force-o a cuspir o veneno primeiro!",
  ui_story_5048_50480201_114_dialog_content = "Sim, Sua Alteza!",
  ui_story_5048_50480201_115_dialog_content = "Cadê o médico mais próximo? Alguém pode mostrar o caminho?",
  ui_story_5048_50480201_116_dialog_content = "Eu sei! Por aqui!",
  ui_story_5048_50480201_117_dialog_content = "Graagh!",
  ui_story_5048_50480201_118_dialog_content = "O quê?!",
  ui_story_5048_50480201_119_dialog_content = "Mova-se!",
  ui_story_5048_50480201_120_dialog_content = "Como os Eclipsitas entraram na Baía dos Pavilhões Gêmeos?!",
  ui_story_5048_50480201_121_dialog_content = "Leve Ernest ao médico primeiro. Nós vamos te dar cobertura.",
  ui_story_5048_50480201_122_dialog_content = "Lembre-se de contar ao médico que Ernest foi envenenado com ravenflame.",
  ui_story_5048_50480201_123_dialog_content = "O-Ok, eu vou!",
  ui_story_5048_50480201_124_dialog_content = "Alteza, por favor, tenha cuidado. Não se esforce demais!",
  ui_story_5048_50480201_125_dialog_content = "Jiu, talvez tenha passado muito tempo desde a última vez que você me viu lidar com um Eclipsita.",
  ui_story_5048_50480302_1_dialog_content = "Majestade, todos os Eclipsitas foram exterminados. Não sobrou nenhum.",
  ui_story_5048_50480302_2_dialog_content = "Ouvi dizer que não havia Eclipsites à solta na Baía dos Pavilhões Gêmeos, então como exatamente essa situação atual aconteceu?",
  ui_story_5048_50480302_3_dialog_content = "É bastante bizarro.",
  ui_story_5048_50480302_4_dialog_content = "Vamos voltar ao restaurante e dar uma olhada ao redor.",
  ui_story_5048_50480302_5_dialog_content = "É definitivamente você! Além de você, quem mais poderia ser o assassino?",
  ui_story_5048_50480302_6_dialog_content = "Meus queridos compatriotas, aconselho que não façam acusações tão descuidadamente - isso pode ser prejudicial à sua sorte!",
  ui_story_5048_50480302_7_dialog_content = "Todos nós ouvimos! Foi você quem usou palavras cruéis para atacar o Sr. Ernest!",
  ui_story_5048_50480302_8_dialog_content = "Sr. Ernest desmaiou logo após você terminar de falar!",
  ui_story_5048_50480302_9_dialog_content = "Ah, o céu sabe, causar mal aos outros só traria consequências negativas para a minha própria vida. Eu nunca faria algo assim.",
  ui_story_5048_50480302_10_dialog_content = "Então, como você sabe que isso é um assassinato premeditado?",
  ui_story_5048_50480302_11_dialog_content = "É definitivamente você! Você é o assassino!",
  ui_story_5048_50480302_12_dialog_content = "Um certo sentimento expresso por tais mercenários vem à mente - viver pela espada, morrer pela espada.",
  ui_story_5048_50480302_13_dialog_content = "Ele viveu sua vida enganando os outros, obscurecendo a verdade... Agora, a verdade não pode salvá-lo.",
  ui_story_5048_50480302_14_dialog_content = "Sua Alteza, Tianxian certamente tem uma língua afiada, mas ele não é uma pessoa de má índole.",
  ui_story_5048_50480302_15_dialog_content = "Se ele realmente foi acusado injustamente, também merece pena.",
  ui_story_5048_50480302_16_dialog_content = "Você está certo, não devemos assistir ele afundar e nem mesmo levantar um dedo para ajudar só por causa de suas decepções passadas.",
  ui_story_5048_50480302_17_dialog_content = "Além disso, não foi fácil para nós viajar até aqui a bordo do Shadowind. Se algum de nós fosse acusado de tal acusação...",
  ui_story_5048_50480302_18_dialog_content = "Ficaria ainda mais difícil para nós estabelecer confiança e trocar informações com os responsáveis aqui no futuro.",
  ui_story_5048_50480302_19_dialog_content = "Sua sabedoria me impressiona, Sua Alteza.",
  ui_story_5048_50480302_20_dialog_content = "Deu certo!",
  ui_story_5048_50480302_21_dialog_content = "Sinta-se à vontade para falar, mas por favor, controle suas mãos!",
  ui_story_5048_50480302_22_dialog_content = "Agarre ele! Não deixe ele fugir!",
  ui_story_5048_50480302_23_dialog_content = "Não vamos nos empolgar agora, pessoal!",
  ui_story_5048_50480302_24_dialog_content = "Provas conclusivas são fundamentais antes de fazer acusações, muito menos antes de exigir punição. Li Tianxian pode ser o principal suspeito aqui, mas é necessário encontrar provas suficientes para condená-lo.",
  ui_story_5048_50480302_25_dialog_content = "Senhora, você tem razão, mas como encontramos evidências?",
  ui_story_5048_50480302_26_dialog_content = "Você pode nos dizer, por favor, para onde Ernest foi e o que ele fez hoje?",
  ui_story_5048_50480302_27_dialog_content = "Nosso chefe tem uma rotina diária bastante regular, e hoje não foi diferente.",
  ui_story_5048_50480302_28_dialog_content = "Isso inclui principalmente inspecionar a cozinha e, às vezes, observar o feedback dos clientes no restaurante.",
  ui_story_5048_50480302_29_dialog_content = "Então, o que ele comeu hoje?",
  ui_story_5048_50480302_30_dialog_content = "Ele não faz refeições regulares porque cada prato da cozinha reserva uma amostra para degustação para ele.",
  ui_story_5048_50480302_31_dialog_content = "Os pratos só são levados às mesas dos clientes quando ele dá sua aprovação.",
  ui_story_5048_50480302_32_dialog_content = "Além disso, você tem certeza de que ele absolutamente não comeu mais nada?",
  ui_story_5048_50480302_33_dialog_content = "Não, eu posso te garantir isso!",
  ui_story_5048_50480302_34_dialog_content = "Nesse caso, o veneno deve estar na comida que o Ernest experimentou.",
  ui_story_5048_50480302_35_dialog_content = "Veneno?",
  ui_story_5048_50480302_36_dialog_content = "É isso mesmo. A razão do colapso de Ernest foi devido ao veneno da chama do corvo em seu organismo.",
  ui_story_5048_50480302_37_dialog_content = "Li Tianxian, você entrou na cozinha hoje?",
  ui_story_5048_50480302_38_dialog_content = "Juro pelo Pergaminho da Ascensão Divina—não!",
  ui_story_5048_50480302_39_dialog_content = "Há alguma testemunha que possa testemunhar a esse respeito?",
  ui_story_5048_50480302_40_dialog_content = "Meu benfeitor... Sr. Victor!",
  ui_story_5048_50480302_41_dialog_content = "Comecei a conversar com meu benfeitor assim que entrei pela porta. Ele pode testemunhar em meu favor!",
  ui_story_5048_50480302_42_dialog_content = "Err... Eu posso testemunhar isso.",
  ui_story_5048_50480302_43_dialog_content = "O que está acontecendo... Isso significa que ele não é culpado?",
  ui_story_5048_50480302_44_dialog_content = "... Se não foi ele, então quem fez isso?",
  ui_story_5048_50480302_45_dialog_content = "Muito obrigado pela sua ajuda, Princesa Dantang. Sem sua intervenção, eu não teria conseguido me livrar dessas suspeitas mesmo que tivesse pulado de volta ao oceano de onde viemos.",
  ui_story_5048_50480302_46_dialog_content = "Não me entenda mal, eu não fiz isso para te ajudar - estou apenas tentando chegar à verdade.",
  ui_story_5048_50480302_47_dialog_content = "Se não for ele, quem mais poderia ser? Nós nem sabemos se nosso chefe está vivo ou morto. O que fazemos agora?",
  ui_story_5048_50480302_48_dialog_content = "Não se preocupe. Não vou desistir, já que me envolvi nesse assunto.",
  ui_story_5048_50480302_49_dialog_content = "Senhorita, por favor, sele a cena com seus colegas e evite tocar até mesmo um grão de poeira. Além disso, preciso pedir que você faça uma lista de todas as pessoas que entraram e saíram do restaurante hoje.",
  ui_story_5048_50480302_50_dialog_content = "Ok, obrigado... A propósito, como devemos nos dirigir a você?",
  ui_story_5048_50480302_51_dialog_content = "Apenas me chame de Dantang.",
  ui_story_5048_50480302_52_dialog_content = "Obrigado, senhorita Dantang!",
  ui_story_5048_50480302_53_dialog_content = "Princesa Dantang, você é uma alma verdadeiramente bela e gentil, e lida com tudo com tanta calma.",
  ui_story_5048_50480302_54_dialog_content = "Você foi isento de suspeita, mas ainda não se afastou.",
  ui_story_5048_50480302_55_dialog_content = "Eu posso não ter sido o culpado, mas tudo isso aconteceu bem diante dos meus olhos. Não posso simplesmente permanecer como um observador passivo.",
  ui_story_5048_50480302_56_dialog_content = "Você tem alguma ideia de como esse caso pode ser resolvido?",
  ui_story_5048_50480302_57_dialog_content = "Na questão de resolver o caso, suas habilidades são superiores às minhas, então eu naturalmente nem sonharia em tentar instruí-lo sobre como lidar com isso.",
  ui_story_5048_50480302_58_dialog_content = "No entanto, enquanto estava sendo arranhado pelas pessoas agora há pouco, eu ouvi algo interessante.",
  ui_story_5048_50480302_59_dialog_content = "Dizem que o proprietário deste restaurante, Ernest, nasceu em uma família de imensa riqueza.",
  ui_story_5048_50480302_60_dialog_content = "Mas, para realizar seu sonho de criar comida de classe mundial, ele foi tão longe a ponto de abrir um restaurante em Twin Pavilions Bay.",
  ui_story_5048_50480302_61_dialog_content = "Ele estabelece requisitos extremamente rigorosos para a comida que serve, e se este restaurante ficasse em segundo lugar na Baía dos Pavilhões Gêmeos, ninguém ousaria afirmar que seu estabelecimento ficaria em primeiro.",
  ui_story_5048_50480302_62_dialog_content = "Quem poderia ter ofendido uma figura tão prestigiosa?",
  ui_story_5048_50480302_63_dialog_content = "Ah, essa pode ser uma lista e tanto.",
  ui_story_5048_50480302_64_dialog_content = "As habilidades culinárias de Ernest são realmente impecáveis, mas ele é um homem distante e arrogante como nunca se viu.",
  ui_story_5048_50480302_65_dialog_content = "Ele frequentemente repreende seus aprendizes, está sempre em conflito com os clientes e até mesmo...",
  ui_story_5048_50480302_66_dialog_content = "Se você tem algo a dizer, diga. Não é hora de fazer mistério.",
  ui_story_5048_50480302_67_dialog_content = "Ele também abriu um café no terraço acima do restaurante.",
  ui_story_5048_50480302_68_dialog_content = "Para os moradores locais, se reunir em um café é o mesmo que sair para uma refeição em Longzhou.",
  ui_story_5048_50480302_69_dialog_content = "E a coisa mais importante sobre uma refeição não é a comida...",
  ui_story_5048_50480302_70_dialog_content = "... São assuntos a serem discutidos ao longo da refeição.",
  ui_story_5048_50480302_71_dialog_content = "Entendo. Este restaurante provavelmente é um dos principais pontos de encontro onde os dignitários locais discutem assuntos importantes.",
  ui_story_5048_50480302_72_dialog_content = "Obrigado pela sua contribuição, Mestre Li.",
  ui_story_5048_50480302_73_dialog_content = "Então sou Mestre Li quando sou útil e um mercenário trapaceiro quando não sou... Vossa Alteza, seus poderes de manipulação superam até mesmo os meus.",
  ui_story_5048_50480302_74_dialog_content = "Tianxian, não abuse da sorte.",
  ui_story_5048_50480302_75_dialog_content = "Se esse assunto envolve autoridades locais, deve ser muito mais complexo do que havíamos previsto anteriormente.",
  ui_story_5048_50480302_76_dialog_content = "Alteza, devemos nos livrar dessa confusão enquanto ainda podemos?",
  ui_story_5048_50480302_77_dialog_content = "Poderíamos deixar o caso com o representante da Guilda Umbraton alojado em Twin Pavilions Bay, aquele que está trabalhando com a família Lin para manter a ordem aqui.",
  ui_story_5048_50480302_78_dialog_content = "Não, isso não serve de jeito nenhum!",
  ui_story_5048_50480302_79_dialog_content = "Sua Alteza ainda não revelou suas intenções. Sobre o que você está falando?",
  ui_story_5048_50480302_80_dialog_content = "Realizei uma adivinhação para você agora mesmo, Sua Alteza...",
  ui_story_5048_50480302_81_dialog_content = "Se você permitir que esse assunto se desenvolva sem sua intervenção, ele acabará afetando você negativamente e dará origem a ramificações intermináveis!",
  ui_story_5048_50480302_82_dialog_content = "Sua Alteza detesta adivinhação. Como ousa mencionar tal coisa na presença dela?",
  ui_story_5048_50480302_83_dialog_content = "Não importa, Jiu.",
  ui_story_5048_50480302_84_dialog_content = "O assunto já chegou a este ponto. Eu não posso simplesmente desistir.",
  ui_story_5048_50480302_85_dialog_content = "Somos estranhos nesta terra, então será difícil para nós começar a investigar os relacionamentos interpessoais dos locais.",
  ui_story_5048_50480302_86_dialog_content = "Mas ainda temos uma pista para investigar.",
  ui_story_5048_50480302_87_dialog_content = "Qual pista?",
  ui_story_5048_50480302_88_dialog_content = "A erva, chama do corvo.",
  ui_story_5048_50480401_1_dialog_content = "Com licença, posso perguntar se você vende uma erva de Longzhou chamada ravenflame aqui?",
  ui_story_5048_50480401_2_dialog_content = "Não, nós não temos isso.",
  ui_story_5048_50480401_3_dialog_content = "Mas ouvi pessoas dizerem que, por mais vasta que seja Twin Pavilions Bay, apenas a sua loja vende essa erva.",
  ui_story_5048_50480401_4_dialog_content = "Você pode comprar de quem disse isso. Nós não temos.",
  ui_story_5048_50480401_5_dialog_content = "Sua atitude está péssima... Gostaria de falar com o proprietário!",
  ui_story_5048_50480401_6_dialog_content = "O que está acontecendo aqui? Me diga qual é o problema e vamos manter isso amigável, hein?",
  ui_story_5048_50480401_7_dialog_content = "Senhora Sheol, eles estão aqui tentando causar problemas.",
  ui_story_5048_50480401_8_dialog_content = "Ai, ai... Quantas vezes eu tenho que te dizer?",
  ui_story_5048_50480401_9_dialog_content = "Qualquer pessoa que entra nesta loja é um cliente, e os clientes são o céu acima, a terra abaixo, a própria carne de nossos corações pulsantes.",
  ui_story_5048_50480401_10_dialog_content = "Como posso confiar em você para cuidar da filial de Twin Pavilions Bay agindo dessa maneira?",
  ui_story_5048_50480401_11_dialog_content = "Mas, Senhora Sheol, você não disse que a erva é apenas para o—",
  ui_story_5048_50480401_12_dialog_content = "Ahem, por que você não vai até o fundo e verifica o inventário primeiro?",
  ui_story_5048_50480401_13_dialog_content = "Minha querida, sinto muito mesmo por isso. Nossa nova assistente de loja claramente ainda não entende completamente a filosofia da nossa marca.",
  ui_story_5048_50480401_14_dialog_content = "Se você se sentiu ofendido, peço desculpas. Por favor, permita-me oferecer uma compensação pelo seu desconforto - todos são bem-vindos a um desconto de doze por cento ao fazer compras aqui hoje!",
  ui_story_5048_50480401_15_dialog_content = "Nós só queremos comprar uma erva chamada ravenflame.",
  ui_story_5048_50480401_16_dialog_content = "Pequena senhora...",
  ui_story_5048_50480401_17_dialog_content = "Só de olhar para você, já percebo que não está aqui para comprar, não é?",
  ui_story_5048_50480401_18_dialog_content = "Senhora Sheol, parece que nada escapa de você.",
  ui_story_5048_50480401_19_dialog_content = "Mas não viemos aqui com a intenção de causar problemas. Estamos investigando um caso.",
  ui_story_5048_50480401_20_dialog_content = "Você ouviu falar sobre o incidente envolvendo o Sr. Ernest que aconteceu esta tarde?",
  ui_story_5048_50480401_21_dialog_content = "Ah, sim. Ernest está envolvido em um conflito entre as facções protecionistas e de livre comércio do distrito oeste de Twin Pavilions Bay.",
  ui_story_5048_50480401_22_dialog_content = "Algo assim estava destinado a acontecer mais cedo ou mais tarde.",
  ui_story_5048_50480401_23_dialog_content = "Eu estava esperando que você pudesse me fazer um favor, Senhora Sheol, e me dizer se você se lembra de alguém comprando alguma chama de corvo.",
  ui_story_5048_50480401_24_dialog_content = "Dessa forma, podemos ser capazes de encontrar o verdadeiro culpado e garantir um ambiente de negócios estável em Twin Pavilions Bay.",
  ui_story_5048_50480401_25_dialog_content = "O ambiente de negócios local não será estabilizado apenas resolvendo este caso. A última coisa que um empresário como eu pode fazer é aborrecer meus clientes, então, por favor, não torne as coisas ainda mais difíceis para mim.",
  ui_story_5048_50480401_26_dialog_content = "Minha bela senhora, receio que você não consiga reconhecer quem está diante de você.",
  ui_story_5048_50480401_27_dialog_content = "Você está na presença da Princesa Zhuohua de Longzhou, Sua Alteza Dantang, uma enviada diplomática da nação nomeada pelos superiores.",
  ui_story_5048_50480401_28_dialog_content = "Se você ofendê-la, pode esquecer de vender mais ravenflame. Na verdade, pode ser impossível conseguir produtos de Longzhou no futuro.",
  ui_story_5048_50480401_29_dialog_content = "Mas se eu tiver estoque e nenhum cliente, não conseguirei fazer negócios de qualquer maneira.",
  ui_story_5048_50480401_30_dialog_content = "Se for esse o caso, talvez possamos nos tornar seus clientes, Senhora Sheol?",
  ui_story_5048_50480401_30X1_dialog_content = "Pequena Senhora, seria uma honra. Além da chama do corvo, temos uma ampla variedade de outros produtos mais diversos do que você pode imaginar.",
  ui_story_5048_50480401_30X2_dialog_content = "Uma ampla variedade de produtos, hein?",
  ui_story_5048_50480401_31_dialog_content = "De acordo com esse raciocínio, você poderia dizer que informações sobre a pessoa que comprou a chama do corvo podem ser consideradas um item negociável em sua loja?",
  ui_story_5048_50480401_32_dialog_content = "Hahaha! Essa mercadoria específica é um pouco complicada, mas se você é realmente sincero em suas intenções, eu não posso ficar parado e não fazer nada.",
  ui_story_5048_50480401_33_dialog_content = "Senhora Sheol, fique tranquila que, desde que o preço seja razoável, lhe darei o dinheiro agora mesmo.",
  ui_story_5048_50480401_34_dialog_content = "Vocês, princesas de Longzhou, certamente vão direto ao ponto! No entanto, o preço deste item não é dinheiro, mas sim uma pessoa.",
  ui_story_5048_50480401_35_dialog_content = "Uma pessoa?",
  ui_story_5048_50480401_36_dialog_content = "Alguns dias atrás, tumultos eclodiram no bazar de mercenários perto de Twin Pavilions Bay, o que me levou a perder uma grande quantidade de mercadorias.",
  ui_story_5048_50480401_37_dialog_content = "Mas ninguém ousa vir à frente para assumir a responsabilidade pelo assunto.",
  ui_story_5048_50480401_38_dialog_content = "Tudo que tenho para me basear é um boato de que uma pessoa misteriosa não identificada apareceu no local do tumulto.",
  ui_story_5048_50480401_39_dialog_content = "Tenho esperado que alguém possa me ajudar a encontrar essa pessoa misteriosa e desvendar a verdade por trás do tumulto.",
  ui_story_5048_50480401_40_dialog_content = "Esse malandro tem alguma característica distintiva?",
  ui_story_5048_50480401_41_dialog_content = "Dizem que a pessoa misteriosa empunhava uma espada pesada, usava um manto escuro e estava coberta de espinhos extremamente afiados.",
  ui_story_5048_50480401_42_dialog_content = "Nossa, essa não é uma pessoa comum.",
  ui_story_5048_50480401_43_dialog_content = "Uh-huh. Se você vai procurar essa pessoa ou não, é com você.",
  ui_story_5048_50480401_44_dialog_content = "Tenho assuntos para resolver agora, mas fique à vontade para ficar na loja o tempo que quiser. Se precisar de mais alguma coisa, é só avisar o vendedor e eu vou lembrá-lo de te dar um desconto!",
  ui_story_5048_50480401_45_dialog_content = "Muito obrigado, Senhora Sheol.",
  ui_story_5048_50480401_46_dialog_content = "Ah, isso mesmo.",
  ui_story_5048_50480401_47_dialog_content = "Se você encontrar essa pessoa misteriosa, não se esqueça de tratá-la bem!",
  ui_story_5048_50480401_48_dialog_content = "Por que trataríamos bem uma vilã assim? Essa Senhora Sheol parece com a Tianxian... Devo admitir, estou bastante confuso.",
  ui_story_5048_50480401_49_dialog_content = "As coisas das quais falo são mistérios da natureza, coisas que naturalmente são difíceis de entender.",
  ui_story_5048_50480401_50_dialog_content = "Quanto a esses modos misteriosos da Senhora Sheol, não consigo dizer se ela está sendo ambígua de propósito ou intencionalmente!",
  ui_story_5048_50480401_51_dialog_content = "Deliberadamente ou intencionalmente... Não são a mesma coisa?",
  ui_story_5048_50480401_52_dialog_content = "Bem, essencialmente, agora cabe a Sua Alteza e à Srta. Jiu procurar por essa pessoa misteriosa.",
  ui_story_5048_50480401_53_dialog_content = "Posso ser habilidoso com inteligência e palavras, mas manusear armas é um trabalho... melhor deixado para aqueles com mais experiência.",
  ui_story_5048_50480401_54_dialog_content = "Vou voltar ao restaurante e aguardar as boas notícias!",
  ui_story_5048_50480401_55_dialog_content = "Então, até mesmo o Mestre Li tem seus momentos de apreensão.",
  ui_story_5048_50480401_56_dialog_content = "Como diz o ditado, um homem sábio conhece seus limites e escolhe suas batalhas - só assim ele pode se tornar um herói. Além disso, eu também não ficarei de braços cruzados.",
  ui_story_5048_50480401_57_dialog_content = "Quando se trata de investigar rumores e averiguar os fatos da situação, ainda tenho alguns truques na manga.",
  ui_story_5048_50480401_58_dialog_content = "Tudo bem, vamos nos dividir e seguir em frente, talvez assim progrediremos mais rápido. Mestre Li, muito obrigado.",
  ui_story_5048_50480401_59_dialog_content = "De nada.",
  ui_story_5048_50480401_60_dialog_content = "Alteza, o bazar de mercenários está logo à frente.",
  ui_story_5048_50480401_61_dialog_content = "É muito maior do que eu esperava, mas isso não deve ser um problema. Vamos fazer o máximo de perguntas possível e procurar testemunhas dos eventos recentes aqui.",
  ui_story_5048_50480401_62_dialog_content = "Ahh! Eclipsitas estão aqui!",
  ui_story_5048_50480401_63_dialog_content = "Eclipsitas de novo? E tão logo após o último ataque...",
  ui_story_5048_50480401_64_dialog_content = "*Rugido*",
  ui_story_5048_50480401_65_dialog_content = "Tenha cuidado, Alteza!",
  ui_story_5048_50480401_66_dialog_content = "Pegue os espinhos!",
  ui_story_5048_50480401_67_dialog_content = "Alteza, você se machucou?!",
  ui_story_5048_50480401_68_dialog_content = "Não. Aquela garota de repente correu até mim e me ajudou a bloquear o ataque do Eclipsita agora há pouco.",
  ui_story_5048_50480401_69_dialog_content = "Aquela garota...",
  ui_story_5048_50480401_70_dialog_content = "Empunhando uma espada pesada, vestindo uma capa e coberto de espinhos?",
  ui_story_5048_50480401_71_dialog_content = "É ela que estamos procurando!",
  ui_story_5048_50480401_72_dialog_content = "Vou adiante e prenderei ela agora.",
  ui_story_5048_50480401_73_dialog_content = "Jiu, não se precipite.",
  ui_story_5048_50480401_74_dialog_content = "Por que não? Ela não é a pessoa que estamos procurando?",
  ui_story_5048_50480401_75_dialog_content = "Ela é a pessoa que estamos procurando, mas olhe só para a postura ereta e a expressão resoluta dela...",
  ui_story_5048_50480401_76_dialog_content = "Ela não parece ser alguém que cometeria atos malignos intencionalmente.",
  ui_story_5048_50480401_77_dialog_content = "Hum...",
  ui_story_5048_50480401_78_dialog_content = "Graagh!",
  ui_story_5048_50480401_79_dialog_content = "Que haja luz!",
  ui_story_5048_50480401_80_dialog_content = "Pela forma como ela está atacando esses Eclipsitas e protegendo os transeuntes, acredito que seja seguro dizer que ela é uma pessoa justa.",
  ui_story_5048_50480401_81_dialog_content = "Você se lembra do que a Senhora Sheol disse?",
  ui_story_5048_50480401_82_dialog_content = "Se você encontrar essa pessoa misteriosa, não se esqueça de tratá-la bem!",
  ui_story_5048_50480401_83_dialog_content = "Ela provavelmente não é a instigadora dos problemas recentes aqui, mas alguém em busca de justiça, como nós.",
  ui_story_5048_50480401_84_dialog_content = "Se for esse o caso, vou dar uma mão para ela.",
  ui_story_5048_50480401_85_dialog_content = "Rugido!!!",
  ui_story_5048_50480401_86_dialog_content = "Arf... arf... arf...",
  ui_story_5048_50480401_87_dialog_content = "Nobre guerreiro, por favor descanse um pouco—",
  ui_story_5048_50480401_88_dialog_content = "A-Você também está aqui para me pegar?",
  ui_story_5048_50480401_89_dialog_content = "Desculpe por assustá-lo. Somos do continente de Longzhou e fomos encarregados nesta terra pela Senhora Sheol para investigar a causa do caos no bazar há alguns dias.",
  ui_story_5048_50480401_90_dialog_content = "Você pode nos dizer o que está acontecendo aqui?",
  ui_story_5048_50480401_91_dialog_content = "Senhora Sheol...?",
  ui_story_5048_50480401_92_dialog_content = "Há todo tipo de pessoas aqui, não apenas mercenários e criminosos, mas também...",
  ui_story_5048_50480401_93_dialog_content = "Aaargh!",
  ui_story_5048_50480401_94_dialog_content = "*Tosse*... E ainda temos esses Eclipsitas rompendo.",
  ui_story_5048_50480401_95_dialog_content = "Um lugar como este... vai manchar a barra das roupas de uma bela nobre.",
  ui_story_5048_50480401_96_dialog_content = "Enquanto não há outros Eclipsitas atacando... aproveite esta chance e vá para casa o mais rápido que puder.",
  ui_story_5048_50480401_97_dialog_content = "Se eu provar que uma nobre pode lutar como um mercenário, você mudará de ideia e me ajudará?",
  ui_story_5048_50480401_98_dialog_content = "*Rugido*",
  ui_story_5048_50480401_99_dialog_content = "... T-Tudo bem! Vou deixar isso com você!",
  ui_story_5048_50480402_1_dialog_content = "Terminei de verificar—nenhum passou despercebido.",
  ui_story_5048_50480402_2_dialog_content = "Obrigado por estar tão disposto a me ajudar...",
  ui_story_5048_50480402_3_dialog_content = "Eu pensei que minha aparência... pudesse te assustar.",
  ui_story_5048_50480402_4_dialog_content = "Consigo ver claramente que você é muito encantadora e adorável. Você me lembra minha irmã mais nova. Como poderia me assustar?",
  ui_story_5048_50480402_5_dialog_content = "Esses... espinhos... no meu corpo...",
  ui_story_5048_50480402_6_dialog_content = "Eles estão doendo?",
  ui_story_5048_50480402_7_dialog_content = "Estou... acostumado com eles.",
  ui_story_5048_50480402_8_dialog_content = "Embora esses espinhos causem dor, você também pode usá-los para lutar e ajudar aqueles que precisam...",
  ui_story_5048_50480402_9_dialog_content = "Sua aparência é realmente admirável!",
  ui_story_5048_50480402_10_dialog_content = "Ai...",
  ui_story_5048_50480402_11_dialog_content = "Eu sou Dantang e aqui ao meu lado está Jiu.",
  ui_story_5048_50480402_12_dialog_content = "Somos de Longzhou e atualmente estamos investigando um caso aqui.",
  ui_story_5048_50480402_13_dialog_content = "A senhora Sheol nos disse que talvez você soubesse de algo, por isso tomamos a liberdade de vir aqui procurar por você.",
  ui_story_5048_50480402_14_dialog_content = "Então... é por isso que você está aqui.",
  ui_story_5048_50480402_15_dialog_content = "Você pode nos dizer seu nome agora?",
  ui_story_5048_50480402_16_dialog_content = "Areia...",
  ui_story_5048_50480402_17_dialog_content = "Meu nome é Areia.",
  ui_story_5048_50480501_1_dialog_content = "Senhorita Areia, quando você mencionou que alguém estava atrás de você, estava falando a verdade?",
  ui_story_5048_50480501_2_dialog_content = "Você pode nos contar sobre isso, se não se importar, é claro.",
  ui_story_5048_50480501_3_dialog_content = "Erm... N-Não me julgue pela minha aparência, eu sou na verdade um mercenário errante.",
  ui_story_5048_50480501_4_dialog_content = "Desde que nasci, tive que conviver com uma doença terrível - esses espinhos negros crescendo no meu corpo.",
  ui_story_5048_50480501_5_dialog_content = "Então agora eu vagueio de lugar em lugar, na esperança de encontrar uma maneira de curar minha condição.",
  ui_story_5048_50480501_6_dialog_content = "Cheguei em Twin Pavilions Bay há pouco tempo.",
  ui_story_5048_50480501_7_dialog_content = "Encontrei um empregador que paga bem no bazar de mercenários.",
  ui_story_5048_50480501_8_dialog_content = "Ei, olhe só para você...",
  ui_story_5048_50480501_9_dialog_content = "Você conhece algum truque que possa machucar sem deixar rastros?",
  ui_story_5048_50480501_10_dialog_content = "Eu-Eu não sei dessas coisas...",
  ui_story_5048_50480501_11_dialog_content = "Confie em mim, o pagamento vai te deixar feliz.",
  ui_story_5048_50480501_12_dialog_content = "Eu nunca machucaria alguém sem um bom motivo...",
  ui_story_5048_50480501_13_dialog_content = "Humpf, tentando agir todo superior e justo aqui?",
  ui_story_5048_50480501_14_dialog_content = "Pessoas como você são um centavo a dúzia; você não tem nada de especial.",
  ui_story_5048_50480501_15_dialog_content = "Pessoas... gostam de mim...?",
  ui_story_5048_50480501_16_dialog_content = "Pensei que se eu o seguisse, poderia encontrar pessoas afetadas pela mesma condição que eu e, talvez, elas pudessem me dizer o que causa esse tipo de doença terrível.",
  ui_story_5048_50480501_17_dialog_content = "Mas depois descobri... ele não conhecia ninguém que entendesse essas coisas.",
  ui_story_5048_50480501_18_dialog_content = "Na verdade, descobriu-se que ele havia encontrado outra maneira de realizar seus planos.",
  ui_story_5048_50480501_19_dialog_content = "Mas você não desistiu da sua busca só por causa disso?",
  ui_story_5048_50480501_20_dialog_content = "Eu simplesmente não conseguia ficar parado... e assistir as pessoas se machucando, então continuei procurando por conta própria.",
  ui_story_5048_50480501_21_dialog_content = "Mas eu fui muito descuidado... me expus no bazar alguns dias atrás.",
  ui_story_5048_50480501_22_dialog_content = "O problema na feira foi na verdade resultado dele me pegando.",
  ui_story_5048_50480501_23_dialog_content = "Então esses Eclipsitas foram realmente trazidos aqui por aquele empregador?",
  ui_story_5048_50480501_24_dialog_content = "Eu sinto muito, muito mesmo... É tudo culpa minha!",
  ui_story_5048_50480501_25_dialog_content = "Então, eu não posso simplesmente desistir e deixar o plano dele dar certo.",
  ui_story_5048_50480501_26_dialog_content = "Parece que os direitos e os erros aqui não são menores do que em Longzhou.",
  ui_story_5048_50480501_27_dialog_content = "O caminho do mundo é buscar o ganho pessoal.",
  ui_story_5048_50480501_28_dialog_content = "Com tanto dinheiro fluindo nos canais de comércio de Twin Pavilions Bay, como este lugar não poderia atrair tanto o bem quanto o mal?",
  ui_story_5048_50480501_29_dialog_content = "Mas acabamos de chegar. Por que já encontramos tantos acontecimentos estranhos?",
  ui_story_5048_50480501_30_dialog_content = "... Você levanta um bom ponto, Jiu. Talvez esses não sejam incidentes isolados. Pode haver alguma conexão oculta entre eles...",
  ui_story_5048_50480501_31_dialog_content = "Areia, você descobriu alguma informação útil durante sua investigação?",
  ui_story_5048_50480501_32_dialog_content = "Hmm... O empregador que mencionei é o chefe de um grupo comercial no distrito oeste de Twin Pavilions Bay.",
  ui_story_5048_50480501_33_dialog_content = "Ele é um membro do que os locais chamam de facção do livre comércio e tem um forte ódio pelos protecionistas...",
  ui_story_5048_50480501_34_dialog_content = "Então, o alvo dele é alguém da facção protecionista.",
  ui_story_5048_50480501_35_dialog_content = "Tudo está conectado.",
  ui_story_5048_50480501_36_dialog_content = "Lembro-me da Senhora Sheol mencionar que Ernest está envolvido em um conflito entre as facções protecionistas e de livre comércio.",
  ui_story_5048_50480501_37_dialog_content = "Na verdade... Eu descobri a identidade do alvo durante minha investigação... Eu queria lidar com os Eclipsitas e ir atrás de um homem chamado Victor.",
  ui_story_5048_50480501_38_dialog_content = "O que você disse?",
  ui_story_5048_50480501_39_dialog_content = "O alvo era... Sr. Victor, o representante da Guilda Umbraton designado para Twin Pavilions Bay.",
  ui_story_5048_50480501_40_dialog_content = "Essa não...",
  ui_story_5048_50480501_41_dialog_content = "Victor é o nome do benfeitor de Tianxian!",
  ui_story_5048_50480501_42_dialog_content = "A-Achoo!",
  ui_story_5048_50480501_43_dialog_content = "Mestre Li, você está bem?",
  ui_story_5048_50480501_44_dialog_content = "Não é nada, por favor, continue.",
  ui_story_5048_50480501_45_dialog_content = "... Então, é claro que acho tudo isso muito angustiante, já que Ernest é meu amigo e a única pessoa que me impulsiona a ser mais resoluto.",
  ui_story_5048_50480501_46_dialog_content = "Embora ele tenha uma língua afiada e eu ocasionalmente responda com algumas críticas minhas, sei que o ponto de vista dele geralmente é muito razoável.",
  ui_story_5048_50480501_47_dialog_content = "Ele ainda não está ciente disso, mas já comecei a promover as práticas dos protecionistas, com o objetivo de torná-las familiares a todos.",
  ui_story_5048_50480501_48_dialog_content = "Mas agora, se ele realmente estiver acabado, os protecionistas ficarão sem seu defensor mais influente...",
  ui_story_5048_50480501_49_dialog_content = "Talvez eu deva reconsiderar minha escolha de apoiar os protecionistas.",
  ui_story_5048_50480501_50_dialog_content = "Como representante da Guilda Umbraton na Twin Pavilions Bay, o Sr. Victor sempre foi conhecido por sua postura distante em relação aos grupos comerciais.",
  ui_story_5048_50480501_51_dialog_content = "Recentemente, porém, ele decidiu não fechar os olhos.",
  ui_story_5048_50480501_52_dialog_content = "Ele também planejava promover as propostas dos protecionistas, tornando-se assim um alvo dos defensores do livre comércio.",
  ui_story_5048_50480501_53_dialog_content = "Mas o Sr. Victor não foi a vítima da trama agora há pouco. Em vez disso, o dono do restaurante, Ernest, foi envenenado e desmaiou.",
  ui_story_5048_50480501_54_dialog_content = "Os comerciantes livres poderiam ter tido dois alvos?",
  ui_story_5048_50480501_55_dialog_content = "Jiu, você se lembra de como Ernest experimentava todas as comidas que saíam da cozinha?",
  ui_story_5048_50480501_56_dialog_content = "O servente do restaurante mencionou esse fato.",
  ui_story_5048_50480501_57_dialog_content = "O Sr. Victor não teve tempo para comer porque Tianxian estava fazendo adivinhações para ele.",
  ui_story_5048_50480501_58_dialog_content = "... O assassino mexeu na comida do Victor.",
  ui_story_5048_50480501_59_dialog_content = "Ernest foi envenenado porque experimentou os pratos de Victor e acabou sendo a vítima em vez do alvo pretendido!",
  ui_story_5048_50480501_60_dialog_content = "Se esse suposto assassino soubesse antecipadamente que Ernest, um protetor, tinha o hábito de provar a comida antes de servir...",
  ui_story_5048_50480501_61_dialog_content = "Envenenar teria sido a estratégia perfeita para matar dois coelhos com uma cajadada só.",
  ui_story_5048_50480501_62_dialog_content = "Então, descobrimos que Tianxian realmente pode salvar vidas às vezes.",
  ui_story_5048_50480501_63_dialog_content = "Falando nisso, Srta. Areia... você disse agora há pouco que o culpado retornou ao bazar dos mercenários?",
  ui_story_5048_50480501_64_dialog_content = "Erm... ele ainda está procurando alguém para ajudá-lo a se livrar do Victor.",
  ui_story_5048_50480501_65_dialog_content = "Essa conspiração contra Victor ainda está em andamento?",
  ui_story_5048_50480501_66_dialog_content = "Socorro! Ajuda!",
  ui_story_5048_50480501_67_dialog_content = "À beira da morte!",
  ui_story_5048_50480501_68_dialog_content = "*Rugido*",
  ui_story_5048_50480501_69_dialog_content = "Não disse que eu encontraria uma pessoa virtuosa que transformaria infortúnios em bênçãos?",
  ui_story_5048_50480501_70_dialog_content = "Tudo que eu vejo aqui são Eclipsitas! Cadê meu salvador virtuoso?!",
  ui_story_5048_50480501_71_dialog_content = "Ah, eu também não pensei que as coisas acabariam assim. A pessoa virtuosa destinada a salvar sua vida não era um nobre de Lumópolis, nem a Princesa de Longzhou...",
  ui_story_5048_50480501_72_dialog_content = "Fui eu, um adivinho sem vergonha. Me desculpe muito!",
  ui_story_5048_50480601_1_dialog_content = "Sr. Victor!",
  ui_story_5048_50480601_2_dialog_content = "Senhorita Dantang!",
  ui_story_5048_50480601_3_dialog_content = "Você está bem? Não se machucou nem um pouco?",
  ui_story_5048_50480601_4_dialog_content = "Estou bem, não estou ferido...",
  ui_story_5048_50480601_5_dialog_content = "E onde está o Tianxian?",
  ui_story_5048_50480601_6_dialog_content = "Mestre Li afastou todos os Eclipsitas sozinho para me salvar...",
  ui_story_5048_50480601_7_dialog_content = "Por favor, resgate-o antes que seja tarde demais!",
  ui_story_5048_50480601_8_dialog_content = "Por que ele não conseguiu prever que enfrentaria um desastre hoje?",
  ui_story_5048_50480601_9_dialog_content = "Fico feliz que você finalmente aprendeu a contar uma piada, mas agora não é a hora.",
  ui_story_5048_50480601_10_dialog_content = "Desculpe, Alteza. Receio que ele possa ter jogado sua vida fora na tentativa de demonstrar sua coragem.",
  ui_story_5048_50480601_11_dialog_content = "... Vamos em frente e dar uma olhada!",
  ui_story_5048_50480601_12_dialog_content = "Jiu, olha!",
  ui_story_5048_50480601_13_dialog_content = "Rugido! Rugido!!!",
  ui_story_5048_50480601_14_dialog_content = "Por que esses Eclipsitas estão se agrupando e rugindo para o chão?",
  ui_story_5048_50480601_15_dialog_content = "É como se estivessem cercando alguém... Espere, será que...",
  ui_story_5048_50480601_16_dialog_content = "Graaagh!",
  ui_story_5048_50480601_17_dialog_content = "Eles nos avistaram!",
  ui_story_5048_50480601_18_dialog_content = "Então vamos eliminá-los rapidamente!",
  ui_story_5048_50480602_1_dialog_content = "Tianxian...",
  ui_story_5048_50480602_2_dialog_content = "Estranho, ele não está aqui?",
  ui_story_5048_50480602_3_dialog_content = "Hum?",
  ui_story_5048_50480602_4_dialog_content = "Hehehe...",
  ui_story_5048_50480602_5_dialog_content = "Jiu, olhe novamente. O que os Eclipsitas estavam cercando agora há pouco?",
  ui_story_5048_50480602_6_dialog_content = "Uma tampa de bueiro que leva aos esgotos...",
  ui_story_5048_50480602_7_dialog_content = "Há uma estatueta de açúcar presa nela?",
  ui_story_5048_50480602_8_dialog_content = "Parece que ele já fez sua fuga astuta, então não precisamos mais nos preocupar.",
  ui_story_5048_50480602_9_dialog_content = "Senhorita Dantang!",
  ui_story_5048_50480602_10_dialog_content = "Areia?",
  ui_story_5048_50480602_11_dialog_content = "Qual é a situação? A Senhora Sheol já foi informada sobre o que está acontecendo?",
  ui_story_5048_50480602_12_dialog_content = "Sim! Também...",
  ui_story_5048_50480602_13_dialog_content = "Além disso, eu trouxe as guildas junto.",
  ui_story_5048_50480602_14_dialog_content = "Senhora Sheol...",
  ui_story_5048_50480602_15_dialog_content = "Finalmente nos reencontramos, Pequena Senhora.",
  ui_story_5048_50480602_16_dialog_content = "Senhora Sheol, muito obrigada pela sua aparição em boa hora. Agora que estamos todos aqui, vamos nos apressar e pegar esse culpado.",
  ui_story_5048_50480602_17_dialog_content = "Não se preocupe com isso. Já que você nos ajudou a encontrar a testemunha-chave...",
  ui_story_5048_50480602_18_dialog_content = "A Guilda de Umbraton, em conjunto com organizações como a Guilda Lin e a União dos Mensageiros, rapidamente capturou o culpado.",
  ui_story_5048_50480602_19_dialog_content = "Assim como você previu, ele admitiu também ser o responsável por planejar o caos dos Eclipsitas recentemente.",
  ui_story_5048_50480602_20_dialog_content = "Agora, em nome de nossas guildas, agradecemos solenemente a você, Enviado de Longzhou, Princesa Dantang, por sua ajuda inestimável.",
  ui_story_5048_50480602_21_dialog_content = "Obrigado, Princesa Dantang, por eliminar os malfeitores para nós!",
  ui_story_5048_50480602_22_dialog_content = "Obrigado, Princesa Dantang! Obrigado, Princesa Dantang!",
  ui_story_5048_50480602_23_dialog_content = "Tenho a impressão de que a Senhora Sheol sabia quem era o verdadeiro culpado desde o início... mas ela queria fazer a prisão em nossos nomes.",
  ui_story_5048_50480602_24_dialog_content = "A Twin Pavilions Bay era originalmente dividida em duas partes e era governada pela Guilda Umbraton e pela Guilda Lin.",
  ui_story_5048_50480602_25_dialog_content = "Seus interesses conflitantes estão tão entrelaçados que, receio que eles próprios não conseguiram resolver o assunto.",
  ui_story_5048_50480602_26_dialog_content = "Nós, sendo forasteiros, pegamos o culpado e assim nos tornamos o escudo deles.",
  ui_story_5048_50480602_27_dialog_content = "Então, estávamos sendo usados?",
  ui_story_5048_50480602_28_dialog_content = "Os benefícios decorrentes desta resolução não são unilaterais - eles também nos ajudaram.",
  ui_story_5048_50480602_29_dialog_content = "Já estabelecemos nossa reputação logo após chegar em Twin Pavilions Bay. As coisas ficarão muito mais fáceis para nós no futuro.",
  ui_story_5048_50480602_30_dialog_content = "Pequenas damas, já terminaram de sussurrar uma para a outra ali?",
  ui_story_5048_50480602_31_dialog_content = "Se houver algo com o qual você esteja insatisfeito, por favor, sinta-se à vontade para me informar. Os representantes da guilda estão todos aqui e com certeza ajudarão a resolver qualquer problema que você possa ter.",
  ui_story_5048_50480602_32_dialog_content = "Você já fez tanto, Senhora Sheol e todos.",
  ui_story_5048_50480602_33_dialog_content = "Eu estava apenas pensando, como vamos lidar com a disputa entre os comerciantes livres e os protecionistas em Twin Pavilions Bay no futuro?",
  ui_story_5048_50480602_34_dialog_content = "Pensei muito nisso hoje e finalmente entendi algo.",
  ui_story_5048_50480602_35_dialog_content = "Todos podemos concordar que Twin Pavilions Bay precisa de sistemas justos e controles adequados.",
  ui_story_5048_50480602_36_dialog_content = "Independentemente de haver apoio da outra facção comercial no futuro, continuarei a promover as propostas dos protecionistas.",
  ui_story_5048_50480602_37_dialog_content = "Mesmo que isso imponha certas restrições às atividades e interesses de outras facções existentes.",
  ui_story_5048_50480602_38_dialog_content = "Restrições...",
  ui_story_5048_50480602_39_dialog_content = "<color=#e8d9bb>Piu, piu, grito—</color>",
  ui_story_5048_50480602_39X1_dialog_content = "<color=#e8d9bb>Sheol olha para o céu com uma expressão pensativa.</color>",
  ui_story_5048_50480602_40_dialog_content = "Todas essas restrições levarão a benefícios muito maiores.",
  ui_story_5048_50480602_41_dialog_content = "O que você acha, pequena senhora?",
  ui_story_5048_50480602_42_dialog_content = "Hmm, não tenho objeções.",
  ui_story_5048_50480602_43_dialog_content = "Bem, ter o apoio da Princesa de Longzhou me faz sentir ainda mais tranquilo.",
  ui_story_5048_50480602_44_dialog_content = "Mas não tem medo de enfrentar tentativas de difamação de facções opositoras no futuro?",
  ui_story_5048_50480602_45_dialog_content = "Medo... Claro que estou com medo.",
  ui_story_5048_50480602_46_dialog_content = "Talvez eu deva considerar contratar um guarda-costas como você.",
  ui_story_5048_50480602_47_dialog_content = "Mas como o Mestre Li disse, eu nasci sob uma estrela da sorte e posso sempre contar com a ajuda de benfeitores virtuosos para transformar meus infortúnios em bênçãos...",
  ui_story_5048_50480602_48_dialog_content = "Ei, por que não peço ao Mestre Li para ser meu guarda-costas?",
  ui_story_5048_50480602_49_dialog_content = "Ahem, aconselho você a reconsiderar.",
  ui_story_5048_50480602_50_dialog_content = "A-Achoo!",
  ui_story_5048_50480602_51_dialog_content = "Julgando por todos os espirros, deve haver muitas pessoas pensando em mim hoje... mas por que ninguém veio até mim para uma adivinhação?",
  ui_story_5048_50480602_52_dialog_content = "<color=#e8d9bb>Splish, splash</color>",
  ui_story_5048_50480602_53_dialog_content = "A Princesa de Ye, o Príncipe de Ji... O Incidente da Família Lin, O Shadowind?",
  ui_story_5048_50480602_54_dialog_content = "Tch, preciso descobrir isso com cuidado.",
  ui_story_5048_50480602_55_dialog_content = "<color=#e8d9bb>Vuuuuuuu!</color>",
  ui_story_5048_50480602_56_dialog_content = "Cobra Yang acima, Boi Yin abaixo. A primavera dá origem ao Boi e à Cobra, preparando-se para quatro estações de tumulto. Será que Longzhou...",
  ui_story_5048_50480602_57_dialog_content = "Não, isso não pode estar certo. Eu devo estar muito cansado para adivinhação agora... certo?",
  ui_story_5048_50480602_58_dialog_content = "Aqui está ele! Aqui está ele!",
  ui_story_5048_50480602_59_dialog_content = "Comendo sozinho! Comendo sozinho!",
  ui_story_5048_50480602_60_dialog_content = "Do que você está falando? Eu ainda não comi nada, só estive esperando vocês dois.",
  ui_story_5048_50480602_61_dialog_content = "Esgotado! Esgotado!",
  ui_story_5048_50480602_62_dialog_content = "Encontre Dantang! Encontre Dantang!",
  ui_story_5048_50480602_63_dialog_content = "Cuide do seu biquinho! Lembre-se de chamá-la de Princesa Dantang quando sair!",
  ui_story_5048_50480602_64_dialog_content = "Princesa?",
  ui_story_5048_50480602_65_dialog_content = "Princesa?",
  ui_story_5048_50480602_66_dialog_content = "Heh, esse tipo de coisa não é opcional.",
  ui_story_5048_50480602_67_dialog_content = "Como mencionado anteriormente pela Guilda Lin, eu sou Dantang, Enviado do Reino Ji de Longzhou.",
  ui_story_5048_50480602_68_dialog_content = "Hoje estou aqui, representando os recursos e a boa vontade que podem ser fornecidos do outro lado do mar.",
  ui_story_5048_50480602_69_dialog_content = "Esperamos que esta rota comercial transoceânica possa não apenas solidificar as comunicações com as guildas de Umbraton...",
  ui_story_5048_50480602_70_dialog_content = "Mas também pode alcançar Lumopolis, a Federação Illumina e até as áreas mais distantes de Northland.",
  ui_story_5048_50480602_71_dialog_content = "...",
  ui_story_5048_50480602_72_dialog_content = "Claro, a cultura e os produtos de Astra também podem entrar no vasto continente de Longzhou através desta rota comercial.",
  ui_story_5048_50480602_72X1_dialog_content = "O equipamento único e os recursos de Astra também podem ajudar Longzhou a superar ameaças à costa...",
  ui_story_5048_50480602_73_dialog_content = "Em resumo, este é um canal de comércio que pode conectar dois continentes!",
  ui_story_5048_50480602_74_dialog_content = "Senhoras e senhores, isso não é apenas um sonho, mas uma realidade ao nosso alcance.",
  ui_story_5048_50480602_75_dialog_content = "Adotantes iniciais podem aproveitar esta oportunidade para embarcar em um caminho destinado a atravessar as eras.",
  ui_story_5048_50480602_76_dialog_content = "Com sua existência, nossa luta contra essas criaturas das trevas também trará mais oportunidades.",
  ui_story_5048_50480602_77_dialog_content = "Vamos!",
  ui_story_5048_50480602_78_dialog_content = "Bem dito. Eu não ouvia palavras tão esperançosas há muito tempo.",
  ui_story_5048_50480602_79_dialog_content = "Senhor das Sombras... O Senhor das Sombras também está aqui!",
  ui_story_5048_50480602_80_dialog_content = "O governante de Umbraton, Lord Istvan!",
  ui_story_5048_50480602_81_dialog_content = "Aceito com prazer sua coragem e sinceridade, em nome da minha organização.",
  ui_story_5048_50480602_82_dialog_content = "Vamos ver se os frutos da nossa cooperação podem realmente carregar o futuro dos nossos dois continentes.",
  ui_story_5048_50480602_83_dialog_content = "Acho que pelo menos servirá como um começo.",
  ui_story_5048_50480602_84_dialog_content = "Um ótimo começo para uma nova era.",
  ui_story_5048_50480602_85_dialog_content = "<color=#e8d9bb>Uau, uau—</color>",
  ui_story_5048_50480602_86_dialog_content = "O vento aumenta.",
  ui_story_5048_50480602_87_dialog_content = "Uma chuva suave amacia Twin Pavilions Bay...",
  ui_story_5048_50480602_88_dialog_content = "Logo estará chegando.",
  ui_story_5048_50480701_1_dialog_content = "<color=#e8d9bb>Alguns dias depois...</color>",
  ui_story_5048_50480701_2_dialog_content = "Alteza, este caminho da montanha é repleto de perigos, por favor, tenha cuidado!",
  ui_story_5048_50480701_3_dialog_content = "As melhores ervas geralmente crescem nos lugares mais perigosos.",
  ui_story_5048_50480701_4_dialog_content = "Quando eu era jovem, minha família inteira pegou a praga e fomos até os picos de montanhas mais perigosos para coletar ervas.",
  ui_story_5048_50480701_5_dialog_content = "O terreno atual, com suas pequenas colinas, não é um problema nem um pouco.",
  ui_story_5048_50480701_6_dialog_content = "Céus... Sua Alteza, talvez você não esteja cansado, mas exauriu todos nós.",
  ui_story_5048_50480701_7_dialog_content = "Aquele dono de restaurante, Ernest, já foi curado.",
  ui_story_5048_50480701_8_dialog_content = "Por que ainda estamos procurando ervas para ele?",
  ui_story_5048_50480701_9_dialog_content = "Embora sua vida não esteja mais em grande perigo, sua saúde deve ter sido gravemente afetada.",
  ui_story_5048_50480701_10_dialog_content = "Neste momento, apenas uma seleção muito específica de ervas pode nutrir rapidamente seu corpo e mente para compensar a deficiência que ainda resta em sua constituição.",
  ui_story_5048_50480701_11_dialog_content = "O Sr. Ernest e eu compartilhamos uma profunda apreciação das qualidades um do outro. Essa amizade é realmente rara e valorizo muito esse vínculo.",
  ui_story_5048_50480701_12_dialog_content = "Então, é claro que devo mostrar minha gratidão a ele imediatamente e deixá-lo experimentar um tônico tradicional de Longzhou.",
  ui_story_5048_50480701_13_dialog_content = "Isso também pode ser considerado uma história muito contada na história da troca culinária entre Astra e Longzhou.",
  ui_story_5048_50480701_14_dialog_content = "Mas será que as ervas de Longzhou realmente podem ser encontradas neste lugar?",
  ui_story_5048_50480701_15_dialog_content = "Já confirmei isso com os moradores locais.",
  ui_story_5048_50480701_16_dialog_content = "Este lugar não tem nossas ervas, mas há um tipo útil conhecido como a goji vermelha, que eles sempre consideraram apenas como uma erva daninha.",
  ui_story_5048_50480701_17_dialog_content = "Choveu bastante há alguns dias, então agora que o céu está limpo, deve ser o momento perfeito para a lycium barbarum vermelha florescer.",
  ui_story_5048_50480701_18_dialog_content = "Fruta vermelha à frente!",
  ui_story_5048_50480701_19_dialog_content = "Delícia! Muito gostoso!",
  ui_story_5048_50480701_20_dialog_content = "Já que vocês dois parecem ser tão habilidosos em procurar alimentos na natureza, podem parar de me pedir melões e tâmaras todos os dias, a partir de agora.",
  ui_story_5048_50480701_21_dialog_content = "Espere, a fruta que Squawk e Jabber estão comendo...",
  ui_story_5048_50480701_22_dialog_content = "É goji vermelho!",
  ui_story_5048_50480701_23_dialog_content = "Encontramos! Na verdade, encontramos!",
  ui_story_5048_50480701_24_dialog_content = "Ah, então essa pequena fruta vermelha é um remédio natural?",
  ui_story_5048_50480701_25_dialog_content = "Tianxian, não coma tantos assim crus, eles aumentam rapidamente seu fogo interno e causam diarreia.",
  ui_story_5048_50480701_26_dialog_content = "Senhorita Jiu, você realmente deveria ter dito algo antes...",
  ui_story_5048_50480701_27_dialog_content = "Grasna, Jabber, você ouviu isso? Coma demais e só terão a si mesmos para culpar pelas consequências...",
  ui_story_5048_50480701_28_dialog_content = "Chega de brincadeira - lembre-se de colher o máximo que puder e encher suas cestas!",
  ui_story_5048_50480701_29_dialog_content = "Sim, Princesa!",
  ui_story_5048_50480701_30_dialog_content = "De nada.",
  ui_story_5048_50480701_31_dialog_content = "Irmãs, eu me pergunto o que vocês duas estão fazendo agora...",
  ui_story_5048_50480701_32_dialog_content = "Tudo está bem aqui e as coisas estão progredindo de maneira ordenada.",
  ui_story_5048_50480701_33_dialog_content = "E eu também tenho uma sensação...",
  ui_story_5048_50480701_34_dialog_content = "Talvez no futuro, eu vivencie acontecimentos ainda mais interessantes em Astra!",
  ui_story_5048_50480701_35_dialog_content = "Também espero encontrar um pianista disposto a tocar uma peça ao lado da minha pipa.",
  ui_story_5048_50480701_36_dialog_content = "Só de pensar nisso...",
  ui_story_5048_50480701_37_dialog_content = "Estou tão animado para ver o que o amanhã vai trazer!"
}
return config
